import{_ as t,o as r,c as o,a3 as n}from"./chunks/framework.BwzYn71E.js";const f=JSON.parse('{"title":"Perfectly Uniform Rational Output","description":"","frontmatter":{"translationSource":{"title":"完美均匀有理数输出","archivedAt":"2026-10-31","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=8DMQhNnwNc2wWjxNQYCtX4","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/perfectly-uniform-rational-output"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/perfectly-uniform-rational-output"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/perfectly-uniform-rational-output"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/perfectly-uniform-rational-output"}]]},"headers":[],"relativePath":"perfectly-uniform-rational-output.md","filePath":"logistics/src/page-8DMQhNnwNc2wWjxNQYCtX4.md"}'),a={name:"perfectly-uniform-rational-output.md"};function i(p,e,s,l,c,u){return r(),o("div",null,[...e[0]||(e[0]=[n('<div class="logistics-content"><span class="logistics-source-anchor" id="完美均匀有理数输出" aria-hidden="true"></span><h1 id="perfectly-uniform-rational-output" tabindex="-1">Perfectly Uniform Rational Output <a class="header-anchor" href="#perfectly-uniform-rational-output" aria-label="Permalink to &quot;Perfectly Uniform Rational Output&quot;">​</a></h1><blockquote><p>Source page ID: <code>8DMQhNnwNc2wWjxNQYCtX4</code> | <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=8DMQhNnwNc2wWjxNQYCtX4" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p>See <a href="/endfield-skydoc/theory-of-perfectly-uniform-rational-output-devices">Theory of Perfectly Uniform Rational-Output Devices</a>.</p><p>Current general implementation methods include:</p><p>@xyIvneu_&#39;s leap-year rules.</p><p>@Cipolla_&#39;s improved leap-year rules incorporating addition.</p><p>@桜夜天華&#39;s recirculating perfectly uniform output.</p><p>All use the following idea, currently believed first introduced by the leap-year rules:</p><p>For any sequence x, if f(x) is perfectly uniform whenever x is perfectly uniform, nesting several f_i(x) preserves perfect uniformity. Rewrite target x_i in multiple steps as f_i(x_(i-1)) until x_0 is easy to construct, then use x_0 and f_i to output x_i.</p><p>The feasible operations found so far are:</p><p>Complementation: swap 0 and 1 in the sequence; f(x) = 1 - x.</p><p>Thinning: retain one 1 out of every n in the sequence, deleting all the others; f(x) = x / n.</p><p>Addition: add 1 to every entry, or add integer n by repeated +1; f(x) = n + x.</p><p>Implementations of the operations:</p><p><span class="mark-red">Add screenshots of result nodes.</span></p><p>Assume x_i = reduced fraction a / b, b = a * q + r, meaning q = b // a, r = b % a.</p><p><strong>Standard leap-year rules:</strong></p><p>x_i = a / b = (1 - r / b) / q = (1 - x_(i-2) ) / q</p><p>x_0 = [1]</p><p><strong>Improved leap-year rules:</strong></p><p>x_i = a / b =(1 - r / b) / q or (1 + r&#39; / b) / q&#39;, using search to select the shorter expansion.</p><p>The former matches the standard leap-year rules.</p><p>In the latter, r&#39; = a-r,q&#39; = q + 1; x_(i-2) = r&#39; / b.</p><p>x_0 = [1]</p><p><strong>Recirculating form:</strong></p><p>x_i = (A + x_(i - 2)) / B</p><p>Restrict possible A values, then search all possible expansions for the shortest.</p><p>x_0 = x_n means recirculation exactly equal to the output serves as input, forcing a two-way split at the end.</p><p>This expansion does not apply to fractions with denominator 2^n*3^m, but those can be constructed by other methods.</p></div>',1)])])}const h=t(a,[["render",i]]);export{f as __pageData,h as default};
